import React, { useState } from "react";
import "./Reviews.css";

const Reviews = () => {
  const [reviews] = useState([
    { name: "Sanjana", rating: 5, comment: "Excellent service! Very professional." },
    { name: "Rohit", rating: 4, comment: "Good job, reasonable pricing." },
    { name: "Kiran", rating: 5, comment: "Super fast booking. Loved it!" },
  ]);

  return (
    <div className="reviews-container">
      <h1>Customer Reviews</h1>

      {reviews.map((r, index) => (
        <div key={index} className="review-card">
          <h3>{r.name}</h3>
          <p className="rating">⭐ {r.rating} / 5</p>
          <p>{r.comment}</p>
        </div>
      ))}
    </div>
  );
};

export default Reviews;
